static int big_cmp(const Big *a, const Big *b) {
    for (int i = NLIMBS - 1; i >= 0; --i) {
        if (a->d[i] < b->d[i]) return -1;
        if (a->d[i] > b->d[i]) return 1;
    }
    return 0;
}

static void big_sub(Big *a, const Big *b) {
    unsigned __int128 borrow = 0;
    for (int i = 0; i < NLIMBS; ++i) {
        unsigned __int128 diff = (unsigned __int128)a->d[i] - b->d[i] - borrow;
        a->d[i] = (uint64_t)diff;
        borrow = (diff >> 64) ? 1 : 0; /* if high bits all 1 from borrow... */
    }
}

/* Portable borrow subtraction */
static void big_sub_u(Big *a, const Big *b) {
    uint64_t borrow = 0;
    for (int i = 0; i < NLIMBS; ++i) {
        uint64_t ai = a->d[i];
        uint64_t bi = b->d[i];
        uint64_t t = ai - bi;
        uint64_t b1 = (ai < bi);
        uint64_t t2 = t - borrow;
        uint64_t b2 = (t < borrow);
        a->d[i] = t2;
        borrow = b1 | b2;
    }
}

static void big_add_u64(Big *a, uint64_t v) {
    unsigned __int128 cur = (unsigned __int128)a->d[0] + v;
    a->d[0] = (uint64_t)cur;
    unsigned __int128 carry = cur >> 64;
    for (int i = 1; i < NLIMBS && carry; ++i) {
        cur = (unsigned __int128)a->d[i] + carry;
        a->d[i] = (uint64_t)cur;
        carry = cur >> 64;
    }
}

static void big_add(Big *a, const Big *b) {
    unsigned __int128 carry = 0;
    for (int i = 0; i < NLIMBS; ++i) {
        unsigned __int128 cur = (unsigned __int128)a->d[i] + b->d[i] + carry;
        a->d[i] = (uint64_t)cur;
        carry = cur >> 64;
    }
}

/* square = n^2 * SCALE; maintain by odd increments: (n+1)^2 - n^2 = 2n+1 */
/* SCALE as Big */
static Big make_scale(void) {
    /* SCALE = 10^90 */
    Big s; memset(&s, 0, sizeof(s));
    /* 10^90 = 5^90 * 2^90; compute via repeated *10 from 1 */
    s.d[0] = 1;
    for (int i = 0; i < 90; ++i) {
        unsigned __int128 carry = 0;
        for (int j = 0; j < NLIMBS; ++j) {
            unsigned __int128 cur = (unsigned __int128)s.d[j] * 10u + carry;
            s.d[j] = (uint64_t)cur;
            carry = cur >> 64;
        }
    }
    return s;
}

long long pe558_answer(void) {
    Big scale = make_scale();
    Big two_scale = scale; big_add(&two_scale, &scale);
    Big square; memset(&square, 0, sizeof(square));
    Big odd = scale; /* starts as 1*SCALE for n=0 -> n=1 step */
    long lead = ZERO_INDEX;
    long long total = 0;
    for (long long n = 0; n < LIMIT; ++n) {
        big_add(&square, &odd);
        big_add(&odd, &two_scale);
        while (lead + 1 < NPOW && big_cmp(&POWERS[lead + 1], &square) <= 0) lead++;
        Big residual = square;
        big_sub_u(&residual, &POWERS[lead]);
        long long terms = 1;
        long pos = lead - 3;
        while (pos >= 0) {
            while (pos >= 0 && big_cmp(&POWERS[pos], &residual) > 0) pos--;
            if (pos < 0) break;
            big_sub_u(&residual, &POWERS[pos]);
            terms++;
            pos -= 3;
        }
        total += terms;
    }
    return total;
}
